# %%
ROOT_DIR = Path.cwd()
input_path = ROOT_DIR / "input"

output_path = ROOT_DIR / output_folder_name

# Set dataset path
dataset_path = Path("/home/joelshin/INFLUENCER")

if not dataset_path.is_dir():
	dataset_path = input_path


# Create folders
Path(input_path / "tmp").mkdir(parents=True, exist_ok=True)
Path(output_path).mkdir(parents=True, exist_ok=True)

# %%

# Build InfluenceCalculator object
ic = InfluenceCalculator(Path(dataset_path / database_name), signed=False, count_thresh=syn_threshold)

# Load meta data
conn = sqlite3.connect(Path(dataset_path / database_name))
meta = pd.read_sql_query("SELECT * FROM meta", conn)
conn.close()

# %%
# Create a mapping from id to cell_type based on noi
id_to_celltype = {}
for cell_type, ids in noi.items():
    for neuron_id in ids:
        id_to_celltype[neuron_id] = cell_type

# Create a copy of meta and update cell_type for ids in noi
meta_updated = meta.copy()
meta_updated.loc[meta_updated['id'].isin(id_to_celltype.keys()), 'cell_type'] = meta_updated.loc[meta_updated['id'].isin(id_to_celltype.keys()), 'id'].map(id_to_celltype)

# %%
# Loop through different seed_ids
for neuron_filename, seed_ids in noi.items():
    # Calculate influence
    influence_df = ic.calculate_influence(seed_ids)
    
    # Join with updated metadata
    influence_df = influence_df.merge(meta_updated, on='id', how='left')
    
    # Save as .csv
    influence_df.to_csv(f"{output_path}/{neuron_filename}_{syn_threshold}thresh_influence.csv", index=False)
    print(f"Saved {neuron_filename}_influence.csv")